def _validate_request(data, client_id):
    """Validate the fields required to handle a request.

    Payload contents are validated by ``process`` because their shape is
    endpoint-specific.  This function only checks the values required by the
    request-handling layer.
    """
    if data is None:
        raise ValueError("request data is required")

    if client_id is None:
        raise ValueError("client_id is required")
    if not isinstance(client_id, str):
        raise TypeError("client_id must be a string")
    if not client_id.strip():
        raise ValueError("client_id must not be empty")


def handle_request(data, client_id, maintenance_mode=False):
    """Validate, rate-limit, and process an incoming API request.

    Rate limiting is skipped during an explicitly requested maintenance
    window.  Request validation still runs in maintenance mode.
    """
    _validate_request(data, client_id)

    if not maintenance_mode and not check_rate_limit(client_id):
        raise RuntimeError("rate limit exceeded")

    return process(data)

